  ", with the defence of Tripoli entrusted to it": ", 트리폴리의 방어를 맡겼습니다.",
  ". Each year, on All Saints' Day, one falcon shall be rendered to the Viceroy of Sicily.": ". 매년 모든 성인의 날에는 매 한 마리를 시칠리아 총독에게 바칩니다.",
  "{0} -{1} CREW": "{0} -{1} 승무원",
