  "{0} accepted. Monsignor {1} comes aboard with the briefs. Set a course for {2}.": "{0}이 허용됩니다. Monsignor {1}이 브리핑을 가지고 옵니다. {2}에 대한 강좌를 설정하세요.",
  "{0} accepts {1} as suzerain.": "{0}은 {1}을 종주국으로 인정합니다.",
  "{0} ACHIEVEMENTS UNLOCKED": "{0} 업적 잠금 해제",
