  "{0} and {1} form an alliance.": "{0}과 {1}이 동맹을 형성합니다.",
  "{0} and {1} have concluded peace.": "{0} 및 {1}이 화해를 체결했습니다.",
  "{0} and {1} improve relations.": "{0} 및 {1}은 관계를 개선합니다.",
  "{0} and {1} make peace.": "{0} 및 {1}이 화해합니다.",
  "{0} and {1} married and had {2} children.": "{0}과 {1}은 결혼하여 {2}명의 자녀를 두었습니다.",
  "{0} and {1} move toward conflict.": "{0}과 {1}이 갈등을 향해 나아가고 있습니다.",
  "{0} and {1} spend Christian blood against one another.": "{0}과 {1}은 서로에게 기독교인의 피를 소비합니다.",
  "{0} and {1} spend Christian blood against one another. His Holiness would send a nuncio under your protection to seek an honorable peace.": "{0}과 {1}은 서로에게 기독교인의 피를 소비합니다. 성하께서는 명예로운 평화를 추구하기 위해 당신의 보호 아래 교황대사를 보내실 것입니다.",
  "{0} at last—the sea gate to Mecca. From here the pilgrims take the road inland. You have carried me to the threshold of the Hajj.": "{0} 마침내 메카로 향하는 바다 문이 탄생했습니다. 여기에서 순례자들은 내륙으로 향합니다. 당신은 나를 하지(Hajj)의 문지방까지 데려다 주었습니다.",
  "{0} at last. Here is the fare I promised.": "드디어 {0}이 나왔습니다. 여기 제가 약속한 요금이 있습니다.",
  "{0} at last. My family will hear your name kindly. Here is the {1} db I owe.": "드디어 {0}이 나왔습니다. 우리 가족은 당신의 이름을 친절하게 듣게 될 것입니다. 여기 제가 빚진 {1} DB가 있습니다.",
  "{0} at last. The treasury will settle our account.": "드디어 {0}이 나왔습니다. 재무부가 우리 계좌를 정산할 것입니다.",
  "{0} attacking canoe{1}.": "{0} 카누를 공격{1}합니다.",
  "{0} away.": "{0} 떨어져 있습니다.",
  "{0} BATTERY DISABLED ({1} DAYS)": "{0} 배터리 비활성화({1}일)",
  "{0} Before we leave, I can show your crew a freshwater spring and where I found edible roots and shellfish.": "{0} 떠나기 전에 승무원들에게 담수 샘과 식용 뿌리와 조개류를 발견한 곳을 보여 드릴 수 있습니다.",
  "{0} Before we leave, I can show your crew a freshwater spring hidden above the beach.": "{0} 떠나기 전에 승무원들에게 해변 위에 숨겨진 담수 샘을 보여드릴 수 있습니다.",
  "{0} Before we leave, I can show your crew where I found edible roots and shellfish.": "{0} 떠나기 전에 승무원들에게 제가 식용 뿌리와 조개류를 발견한 곳을 알려드릴 수 있습니다.",
  "{0} believes {1} is within reach. I should find it, then return to {2}.": "{0}은 {1}이(가) 도달할 수 있는 거리에 있다고 믿습니다. 찾아서 {2}로 돌아가야 합니다.",
  "{0} bombarded {1} and silenced its guns. The quays remain closed for {2}; you must put back to sea.": "{0}이 {1}에 포격을 가하고 총을 침묵시켰습니다. 부두는 {2} 동안 폐쇄됩니다. 바다로 돌려보내야 합니다.",
  "{0} Both courts have now spoken. Rome will act upon the counsel you carry home.": "{0} 이제 두 법원 모두에서 진술이 이루어졌습니다. 로마는 당신이 집으로 가져간 조언에 따라 행동할 것입니다.",
  "{0} brought aboard for {1} db.": "{0}이 {1} DB에 포함되었습니다.",
  "{0} calf": "{0} 송아지",
  "{0} cannot be {1} without permission from the government in {2}. We must take the emissaries there first.": "{0}은 {2}에서 정부의 허가 없이는 {1}일 수 없습니다. 먼저 사절을 그곳으로 데려가야 합니다.",
  "{0} captured": "{0} 캡처됨",
  "{0} CAPTURED +{1} DB": "{0} 캡처됨 +{1} DB",
  "{0} CASKS CANNOT TAKE MORE": "{0} 캐스크는 더 이상 담을 수 없습니다",
  "{0} chunk {1}": "{0} 청크 {1}",
  "{0} chunk manifest": "{0} 청크 매니페스트",
  "{0} colors. Keep the spoils; return for": "{0} 색상. 전리품을 보관하십시오. 반환하다",
  "{0} comes aboard with the briefs. Set a course for {1}.": "{0}이 브리핑과 함께 참여합니다. {1}에 대한 강좌를 설정하세요.",
  "{0} CONDEMNS {1}": "{0} 비난 {1}",
  "{0} conquest prize": "{0} 정복 상금",
