  "{0} crew / {1} hull": "{0} 승무원 / {1} 선체",
  "{0} CREW LOST": "{0} 승무원 손실",
  "{0} CREW LOST ASHORE": "{0} 선원이 해변에서 길을 잃었습니다.",
