  "Closely woven canvas holds its shape in a fresh breeze.": "촘촘하게 짜여진 캔버스는 신선한 바람에도 형태를 유지합니다.",
  "Cloud Cover Performance Benchmark": "클라우드 커버 성능 벤치마크",
  "Cloves drew the Portuguese to your shore. Your family mistook their appetite for a guarantee.": "정향은 포르투갈인들을 해안으로 끌어들였습니다. 귀하의 가족은 자신의 욕구를 보증으로 착각했습니다.",
  "CMD": "명령",
  "Coastal canoe crews recognized your sail offshore. Market runners are already spreading word of your return.": "해안 카누 승무원이 귀하의 해상 항해를 인식했습니다. 시장 주자들은 이미 귀하의 수익에 대한 소문을 퍼뜨리고 있습니다.",
  "Coastal Pinnace": "연안 피나스선",
  "Coastal Surveyor": "해안 측량사",
  "coastal waters": "연안 해역",
  "Coasters call with every change of wind, but an unusual cargo can still stir the whole market.": "코스터는 바람이 바뀔 때마다 호출되지만, 특이한 화물은 여전히 전체 시장을 뒤흔들 수 있습니다.",
  "Coaxes the ship through turns and closer to the wind.": "배를 회전시키고 바람에 더 가까이 다가가게 합니다.",
  "Cod": "대구",
  "Coffee first. Then bearings. Then whales.": "먼저 커피. 그 다음은 베어링. 그런 다음 고래.",
  "Coir Cordage": "코이어 밧줄",
  "Cold": "감기",
  "Cold, isolation, and scurvy destroyed Saint Croix. De Monts and Poutrincourt will try again in sheltered Annapolis, relying on nearby Mi'kmaq knowledge.": "추위, 고립, 괴혈병으로 인해 Saint Croix는 파괴되었습니다. De Monts와 Poutrincourt는 인근 Mi'kmaq 지식에 의존하여 안전한 아나폴리스에서 다시 시도할 것입니다.",
  "COLLISION -{0} HULL": "충돌 -{0} 선체",
  "Colonist": "식민지 주민",
  "colonists, sailors, and the first planting season": "식민지 주민, 선원 및 첫 번째 재배 시즌",
  "colony:{0}": "식민지:{0}",
  "Combat focused": "전투 중심",
  "Commission accepted. Capture {0} for {1}.": "커미션이 승인되었습니다. {1}에 대해 {0}을 캡처하세요.",
  "Commission fulfilled. Earned {0} db. Standing greatly improved.": "커미션이 완료되었습니다. {0} DB를 획득했습니다. 스탠딩이 크게 향상되었습니다.",
  "common houses, roofs, and a defensive platform": "일반 주택, 지붕 및 방어 플랫폼",
