  "community emissary": "지역사회 사절",
  "community messenger": "커뮤니티 메신저",
  "Compact horn-and-sinew bows loose quickly from a crowded deck.": "콤팩트한 뿔과 힘줄로 이루어진 활은 혼잡한 갑판에서 빠르게 느슨해집니다.",
  "COMPARE WITH {0}": "{0}과 비교",
  "Complete a captain's main goal and return home.": "선장의 주요 목표를 달성하고 집으로 돌아갑니다.",
  "Complete a shore scavenging expedition.": "해안 청소 탐험을 완료하세요.",
  "Complete current job": "현재 작업을 완료하세요.",
  "Complete the mission {0} db": "{0} DB 임무를 완료하세요",
  "Completed Mediterranean natural history": "완성된 지중해 자연사",
  "Completed the great bestiary": "위대한 우화집을 완성했습니다",
  "Composite Recurve Bows": "복합 리커브 활",
  "Concepcion endures at Penco as a military and administrative center, sustained from Peru on a frontier Spain has not subdued.": "콘셉시온은 Penco에서 군사 및 행정 중심지로 지속되었으며, 스페인이 정복하지 못한 국경의 페루에서 유지되었습니다.",
  "Concepcion is asking for powder, not ceremony.": "콘셉시온은 의식이 아닌 가루를 요구하고 있습니다.",
  "Confirm {0}": "{0} 확인",
  "Confucian tradition": "유교 전통",
  "Conquer a port for your nation.": "당신의 나라를 위해 항구를 정복하세요.",
  "Conqueror": "정복자",
  "Continue": "계속",
  "Continue into port": "항구로 계속 이동",
  "CONTROLLED SPICES SURRENDERED {0}": "통제된 향신료가 항복했습니다 {0}",
  "Cooperation as a weapon. That is a finer observation than any measurement of tooth or paw, and one our moralizing bestiaries would likely misunderstand.": "무기로서의 협력. 이는 치아나 발을 측정하는 것보다 더 정밀한 관찰이며, 우리의 도덕적 우화자들이 오해할 가능성이 있는 것입니다.",
  "Costly self-igniting pistols are deadly at close range and useful in a landing party.": "값비싼 자동 점화 권총은 근거리에서 치명적이며 상륙 작전에 유용합니다.",
  "Cotton and tobacco occupy the promoters, but neither feeds a hungry harbor town.": "면화와 담배가 발기인을 차지하고 있지만 둘 다 배고픈 항구 도시에 식량을 공급하지 않습니다.",
  "COULD NOT END CURRENT VOYAGE": "현재 항해를 종료할 수 없습니다.",
  "Court notice: {0} is gone. {1} now rules {2}.": "법원 통지: {0}이 사라졌습니다. {1}은 이제 {2}을 규칙으로 삼습니다.",
  "COVER": "커버",
  "Cranes swing over the crowded wharf while guild clerks tally barrels, bales, and ships waiting on the tide.": "크레인이 붐비는 부두 위로 흔들리고 길드 직원은 조수를 기다리고 있는 통, 더미, 선박을 집계합니다.",
  "cranes, locks, hoops, and sugar-mill repairs": "크레인, 자물쇠, 고리 및 설탕 공장 수리",
  "Create a domestic matchlock industry in Japan.": "일본 국내 화승총 산업을 창출합니다.",
  "Creation and destruction from one furnace. Mark the fresh flows separately from the cultivated slopes; the island's prosperity and danger share a source.": "하나의 용광로에서 생성과 파괴가 가능합니다. 경작된 경사면과 별도로 신선한 흐름을 표시하십시오. 섬의 번영과 위험은 근원을 공유합니다.",
  "Crew": "승무원",
