  "Crowns change hands: {0} now rules {1} after {2}.": "크라운이 주인을 바꿉니다. 이제 {0}이 {2} 이후 {1}을 지배합니다.",
  "Crunch. Crunch.": "위기. 결정적 시기.",
  "curing cod for the voyage back across the Atlantic": "대서양을 건너는 항해를 위해 대구를 치료합니다",
  "curing fish and preserving provisions for port laborers": "항구 노동자를 위한 물고기 치료 및 보존 규정",
  "Current battery: {0}. Faster locks and longer culverins improve reload, damage, and range. Purse {1} db.": "현재 배터리: {0}. 더 빠른 잠금 장치와 더 긴 컬버린은 재장전, 손상 및 범위를 향상시킵니다. 지갑 {1} DB.",
  "Current gear: {0}. Other nets offered: {1}. Purse {2} db.": "현재 장비: {0}. 제공되는 기타 네트: {1}. 지갑 {2} DB.",
  "Current harpoon: {0}. A stronger line and truer shaft improve the odds of holding a surfaced whale. Purse {1} db.": "현재 작살: {0}. 더 강한 라인과 더 정확한 샤프트는 표면에 떠 있는 고래를 잡을 가능성을 높여줍니다. 지갑 {1} DB.",
  "CURRENT SHIP WILL BE REPLACED": "현재 선박이 교체됩니다",
  "Cusabo food and support have kept the settlement alive, but the Proprietors' own crops have disappointed them.": "쿠사보의 식량과 지원으로 정착지가 살아있게 되었지만, 소유주의 농작물은 그들을 실망시켰습니다.",
  "Custom": "맞춤",
  "Custom targets set. Crew {0}/{1}, guns {2}/{3}.{4}{5}": "맞춤 타겟이 설정되었습니다. 승무원 {0}/{1}, 총 {2}/{3}.{4}{5}",
