  "Deliver a passenger safely to their destination.": "승객을 목적지까지 안전하게 인도하세요.",
  "Deliver available ingredients": "사용 가능한 재료 배달",
  "Deliver five passengers safely in one voyage.": "한 번의 항해로 5명의 승객을 안전하게 운송하세요.",
  "Delivered {0} x{1}. {2} still needed; these stores buy the colony {3} more days.": "{0} x{1}을 게재했습니다. {2}이 여전히 필요합니다. 이 상점에서는 식민지를 {3}일 더 구매합니다.",
  "Delivered {0} x{1}. {2} still needed.": "{0} x{1}을 게재했습니다. {2}이 여전히 필요합니다.",
