  "Portuguese factors keep a small trading post here, joining Patani to their routes through Malacca and Siam.": "포르투갈 항구 상인들은 이곳에 작은 교역소를 두고 말라카와 시암을 통과하는 항로에 파타니와 합류합니다.",
  "Portuguese factory and tribute station": "포르투갈 공장 및 공물 기지",
