  "Portuguese fortress and factory": "포르투갈어 요새와 공장",
  "Portuguese masons are raising a fort and factory beside the clove anchorage; their flag already covers their warehouse trade.": "포르투갈 석공들은 정향 정박지 옆에 요새와 공장을 세우고 있습니다. 그들의 깃발은 이미 창고 거래를 다루고 있습니다.",
  "Portuguese merchant settlement": "포르투갈 상인 정착지",
  "Portuguese merchants keep a privileged quarter around the new harbor, while Japanese officials retain the city.": "포르투갈 상인들은 새로운 항구 주변에 특권 구역을 유지하고, 일본 관리들은 도시를 유지합니다.",
