  "proof the first locally made matchlocks beyond the city walls": "성벽 너머에서 최초로 현지에서 제작된 화승총을 증명하다",
  "Providence needs trade cloth to honor its agreements and outfit new arrivals.": "프로비던스는 계약을 존중하고 새로 도착한 옷을 입기 위해 옷감이 필요합니다.",
  "Providence now offers a refuge for conscience under civil government, founded through negotiation with Narragansett leaders rather than a Massachusetts patent.": "프로비던스는 이제 매사추세츠 특허가 아닌 나라간셋 지도자들과의 협상을 통해 설립된 시민 정부 하에서 양심의 피난처를 제공합니다.",
  "Prrrraaaah!": "으아아아아!",
  "Puncak Jaya is a wall of pale, sheer rock above steaming equatorial forest, with snow and ice hidden in its highest folds. I had never seen cold and jungle pressed so close together.": "뿐착자야(Puncak Jaya)는 김이 모락모락 나는 적도 숲 위의 창백하고 깎아지른 듯한 바위 벽으로, 가장 높은 주름 부분에는 눈과 얼음이 숨겨져 있습니다. 나는 추위와 정글이 이렇게 가까이 붙어 있는 것을 본 적이 없습니다.",
  "Purchase {0}": "{0} 구매",
  "Purchase {0}-day Portuguese cartaz": "{0}일 포르투갈 카르타즈 구매",
  "Purchase {0}; {1} doubloon vessel trade-in": "{0} 구매; {1} 금화 선박 보상 판매",
  "Purchase a license, settle the fine, surrender controlled spice cargo, or answer to our guns.": "면허를 구입하고, 벌금을 정산하고, 통제된 향신료 화물을 인도하거나, 우리 총에 응답하십시오.",
  "Purchase prices -{0}": "구매 가격 -{0}",
  "Put every barrel on my account. Except the wine. I believe the wine has already put me on its account.": "모든 통을 내 계정에 넣어주세요. 와인만 빼고요. 나는 포도주가 이미 나를 그 책임에 빠뜨렸다고 믿습니다.",
  "Put to sea": "바다에 던지다",
  "Put your bow {0} of {1} and watch for Captain {2}.": "{1}의 활 {0}을 놓고 선장 {2}을 지켜보세요.",
  "Put your bow {0} of {1} and watch for Captain {2}. That rogue carries one scrap of a map worth twelve men's lives.": "{1}의 활 {0}을 놓고 선장 {2}을 지켜보세요. 그 도적은 열두 사람의 목숨에 해당하는 지도 조각 하나를 가지고 있습니다.",
  "Pyramids in Nubia! How many kingdoms has the Nile carried?": "누비아의 피라미드! 나일강에는 얼마나 많은 왕국이 있었나요?",
  "Quaker": "퀘이커",
  "quays, warehouses, and houses around the new anchorage": "새 정박지 주변의 부두, 창고 및 주택",
  "Quebec needs grain before ice closes the St. Lawrence.": "퀘벡에는 얼음이 세인트 로렌스를 덮기 전에 곡물이 필요합니다.",
  "Quebec now anchors New France at the river narrows, sustained by shipping, fur trade, and its Indigenous alliances.": "퀘벡은 이제 해운, 모피 무역, 원주민 동맹을 통해 유지되는 좁은 강에 뉴프랑스를 정박하고 있습니다.",
