  "Raccoon": "너구리",
  "Raichur's victory procession was splendid. I noticed your paymaster absent from it.": "라이추르의 승리 행렬은 화려했다. 나는 당신의 급여담당자가 그 자리에 없는 것을 알아차렸습니다.",
  "Rainier loomed above the inland waters, a massive white volcano cut by rivers of ice. Even at great distance it dwarfed the forested ridges in front of it.": "레이니어는 얼음 강에 의해 절단된 거대한 흰색 화산인 내륙 바다 위에 우뚝 솟아 있었습니다. 먼 거리에서도 앞에 있는 숲이 우거진 능선을 왜소하게 만들었습니다.",
  "Raise Our Colors": "우리의 색깔을 높이세요",
  "Reach {0}": "{0}에 도달",
  "Reads shoals and handles a net with confidence.": "떼를 읽고 자신있게 그물을 다룹니다.",
