  "REC {0}:{1}": "녹화 {0}:{1}",
  "Receive the answer": "답변 받기",
  "Recife has become the reef-sheltered warehouse port of Pernambuco. Sugar comes down from the mills, and Atlantic hulls crowd the channel.": "헤시피는 암초로 보호된 페르남부쿠의 창고 항구가 되었습니다. 설탕은 공장에서 내려오고 대서양 선체는 수로로 가득 차 있습니다.",
  "Recife needs a full sugar cargo to prove the new harbor can pay.": "헤시피는 새로운 항구가 지불할 수 있다는 것을 증명하기 위해 설탕 화물을 가득 채워야 합니다.",
