  "Reconstructed ash and yew bows complete the longship's fighting equipment.": "재구성된 재와 주목 활은 롱쉽의 전투 장비를 완성합니다.",
  "Recovered all {0} pieces of Captain {1}'s map, found the island, and fought the old crew home.": "{0} 선장의 {1} 지도 조각을 모두 회수하고 섬을 찾은 다음 옛 선원들과 싸워 집으로 돌아갔습니다.",
