  "Royal foundry battery": "왕실 주조 배터리",
  "Royal Lancaran": "왕실 란차란",
  "Royal license for trade in the Spanish Indies": "스페인령 인도 무역에 대한 왕실 허가증",
  "Rrrrraow!": "우르르르르!",
  "Rrrrroaaaah!": "으으아아아아!",
