  "Runners and coastal craft carry news from this landing toward the high country.": "주자와 연안 선박은 이번 상륙 소식을 고지대를 향해 전합니다.",
  "Running in ballast.": "밸러스트에서 실행 중입니다.",
  "Runs a practiced and orderly gun deck.": "연습되고 질서정연한 총기 갑판을 운영합니다.",
