  "SAFE PASSAGE ALREADY SECURED": "안전한 통행은 이미 확보되었습니다",
  "SAFE PASSAGE REFUSED": "안전한 통행이 거부됨",
  "Sail {0} deg closer to wind": "바람에 {0}도 더 가까이 항해하세요.",
  "SAIL / {0} DEG": "항해 / {0} DEG",
  "Sail every ship type across any number of voyages.": "원하는 횟수만큼 모든 선박 유형을 항해하세요.",
  "Sail five different ship types across any number of voyages.": "항해 횟수에 관계없이 다섯 가지 유형의 선박을 항해하세요.",
  "Sail two different ship types across any number of voyages.": "항해 횟수에 관계없이 두 가지 다른 선박 유형을 항해하십시오.",
  "Sailing ship": "범선",
  "Sailing the East China Sea Before Meeting the Panda": "판다를 만나기 전 동중국해 항해",
  "Sailing the South China Sea Before Meeting the Panda": "판다를 만나기 전 남중국해 항해",
  "sails, vestments, bedding, and a hospital": "돛, 의복, 침구 및 병원",
  "Saint Croix taught us to fear cold more than distance. Bring": "Saint Croix는 우리에게 거리보다 추위를 더 두려워하라고 가르쳤습니다. 가져오다",
  "Sale prices +{0}": "할인가 +{0}",
  "salesPitch": "판매피치",
  "Salisbury Plain": "솔즈베리 평원",
  "Salmon": "연어",
  "Salvador needs grain while officials, soldiers, builders, and clergy continue to arrive.": "살바도르에는 곡물이 필요하고 공무원, 군인, 건축업자, 성직자는 계속해서 도착합니다.",
  "Salvador now stands as Brazil's fortified capital, with government on the heights and Atlantic commerce below.": "살바도르는 이제 높은 곳에 정부가 있고 아래에 대서양 상업이 있는 브라질의 요새화된 수도로 우뚝 서 있습니다.",
  "Sampan": "Sampan",
  "San Agustin needs grain before storms or war cut off the harbor.": "산아구스틴은 폭풍이나 전쟁으로 인해 항구가 폐쇄되기 전에 곡물이 필요합니다.",
  "sangat singer": "상가 가수",
  "Sangat's gift": "산가트의 선물",
  "Sanriku whaling grounds": "산리쿠 포경장",
  "Santiago de Leon de Caracas now holds the valley, though its Indigenous name has already proved stronger than the one in the charter.": "산티아고 데 레온 데 카라카스(Santiago de Leon de Caracas)는 현재 계곡을 보유하고 있지만 원주민 이름은 이미 헌장의 이름보다 더 강한 것으로 입증되었습니다.",
  "Sao Paulo de Luanda has become Portugal's fortified Angolan port. Its Atlantic wealth is inseparable from warfare and the traffic in enslaved people.": "상파울루 데 루안다는 포르투갈의 요새화된 앙골라 항구가 되었습니다. 대서양의 부는 전쟁과 노예무역과 불가분의 관계에 있습니다.",
  "Sao Sebastiao cannot secure Guanabara without more powder.": "상 세바스티앙은 더 이상의 화약 없이는 과나바라를 확보할 수 없습니다.",
  "Sao Sebastiao has secured Guanabara Bay for Portugal. Around the old redoubt, Rio de Janeiro is becoming a true port.": "Sao Sebastiao는 포르투갈을 위해 Guanabara Bay를 확보했습니다. 오래된 보루 주변에서 리우데자네이루는 진정한 항구가 되어가고 있습니다.",
  "Sapa Inca": "사파 잉카",
  "Sapa Inca {0}": "사파 잉카 {0}",
  "Sardine": "정어리",
  "SAVE COULD NOT BE LOADED": "저장한 내용을 로드할 수 없습니다.",
  "SAVE FAILED - RETRYING": "저장 실패 - 재시도 중",
  "SAVE RESTORED": "저장이 복원되었습니다.",
  "SCAVENGE": "수색",
