  "SE": "SE",
  "SEA": "바다",
  "SEA ICE PARTED THE HARPOON LINE": "바다 얼음이 작살 선을 갈라 놓았습니다",
  "Sea Venture survivors built Deliverance and Patience from Bermuda cedar before reaching Jamestown. Their account now inspires a town at St. George's.": "Sea Venture 생존자들은 제임스타운에 도착하기 전에 버뮤다 삼나무로 구원과 인내를 건설했습니다. 그들의 이야기는 이제 St. George's의 한 마을에 영감을 줍니다.",
  "Sea-road renewal": "바다길 리뉴얼",
  "Sealed delivery packet": "봉인된 배송 패킷",
