  "seed and a first-year reserve": "시드 및 1년차 예비비",
  "seed and food during the overland migration": "육로 이동 중 종자와 식량",
  "seed and food insurance after the first northern winter": "첫 번째 북부 겨울 이후 종자 및 식품 보험",
  "seed and food while river gardens are established": "강 정원이 조성되는 동안 종자와 식량",
  "seed and provisions for the first deliberate planting": "최초의 의도적 재배를 위한 종자 및 규정",
  "seed and provisions that do not depend on seizure from local fields": "현지 밭에서 압수하지 않는 종자 및 식량",
  "seed stock and the colony's early export experiments": "종자 재고와 식민지의 초기 수출 실험",
  "Seek illicit market": "불법시장을 노려라",
  "Sekibune": "세키부네",
  "Sell {0} x{1}": "{0} x{1} 판매",
